export type ParsedPlaceLimitInstruction<
  TProgram extends string = typeof LVRT_ENGINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Owner or delegate; pays the order's rent (refunded to the keeper that fills it, or the owner on cancel). */
    signer: TAccountMetas[0];
    margin: TAccountMetas[1];
    market: TAccountMetas[2];
    order: TAccountMetas[3];
    systemProgram: TAccountMetas[4];
  };
  data: PlaceLimitInstructionData;
};

export function parsePlaceLimitInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedPlaceLimitInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 5) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 5,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      signer: getNextAccount(),
      margin: getNextAccount(),
      market: getNextAccount(),
      order: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getPlaceLimitInstructionDataDecoder().decode(instruction.data),
  };
}
